{"sql": "-- Create base tables needed for the operations
CREATE TABLE persons (
    id SERIAL PRIMARY KEY,
    name VARCHAR(100)
);

CREATE TABLE baseball_offensive_stats (
    id SERIAL PRIMARY KEY,
    person_id INTEGER REFERENCES persons(id),
    hits INTEGER,
    at_bats INTEGER,
    home_runs INTEGER,
    rbi INTEGER
);

CREATE TABLE person_event_metadata (
    id SERIAL PRIMARY KEY,
    person_id INTEGER REFERENCES persons(id),
    event_date DATE,
    game_id INTEGER
);

CREATE TABLE injury_phases (
    id SERIAL PRIMARY KEY,
    person_id INTEGER REFERENCES persons(id),
    start_date DATE,
    end_date DATE
);"}

{"sql": "CREATE TABLE team_performance_summary (
    summary_id SERIAL PRIMARY KEY,
    metric_name VARCHAR UNIQUE,
    metric_value DECIMAL
);"}
